import{z as s,x as p,o as r,c as h,q as o,j as E,D as i,d as e,s as B,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Kakutani 不动点","description":"","frontmatter":{"title":"Kakutani 不动点","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/kakutani-fixed-point.md","filePath":"econ/kakutani-fixed-point.md","lastUpdated":1791063341000}'),u={name:"econ/kakutani-fixed-point.md"};function d(A,a,c,k,x,m){const t=p("Mermaid");return r(),h("div",null,[a[2]||(a[2]=o('<h1 id="kakutani-不动点" tabindex="-1">Kakutani 不动点 <a class="header-anchor" href="#kakutani-不动点" aria-label="Permalink to &quot;Kakutani 不动点&quot;">​</a></h1><div class="epigraph"><p>对应把一点送到一个集合；在紧凸上，上半连续、非空紧凸值的自对应必有 $x\\in\\Phi(x)$。</p><footer>—— 据 Kakutani, Duke Mathematical Journal, 1941；Debreu, Theory of Value, 1959；Mas-Colell, Whinston and Green 第 17 章整理</footer></div><p>上一课<a href="/econ/brouwer-fixed-point">Brouwer 不动点</a>管连续函数。马歇尔需求在完全替代时是一段线段，最优反应在无差异时是一个面：对象是对应 \\(\\Phi:C\\rightrightarrows C\\)，不是函数。缺口是把不动点改写成 \\(x\\in\\Phi(x)\\)。上半连续的精确定义下一课才展开；本课先把 Kakutani 的假设当黑箱用起来，并标明后课均衡、混合策略纳什缺的就是这四条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(C\\subset\\mathbb{R}^n\\) 非空紧凸。\\(\\Phi:C\\rightrightarrows C\\) 满足：(i) 每点 \\(\\Phi(x)\\) 非空紧凸；(ii) \\(\\Phi\\) 上半连续（闭图在紧值时与之等价）。则存在 \\(x^*\\in C\\) 使 \\(x^*\\in\\Phi(x^*)\\)。Brouwer 是 \\(\\Phi(x)=\\{f(x)\\}\\) 的特例：单点集凸且紧，连续函数的图闭。</p><p>超额需求若集值，构造 \\(\\Phi(p)\\) 为「被 \\(z(p)\\) 改善的价格方向」或直接对需求对应加总，不动点仍是出清。有限正规形式博弈：混合策略单纯形上，对手混合给定时最佳反应是线性规划的最优面，凸紧；期望收益连续给出上半连续。于是<a href="/econ/mixed-strategy">混合策略与存在性</a>是 Kakutani 的实例。本课不把 Nash 1950 重写一遍。</p><h3 id="凸值不能省" tabindex="-1">凸值不能省 <a class="header-anchor" href="#凸值不能省" aria-label="Permalink to &quot;凸值不能省&quot;">​</a></h3><p>上半连续且紧值已经能保证图闭，没有凸值仍可没有不动点：想一想把圆分成上下两弧的对应，或两点集 \\(\\{0,1\\}\\) 上 \\(\\Phi(0)=\\{1\\}\\)、\\(\\Phi(1)=\\{0\\}\\)。经济学对应：非凸偏好让需求是两端、不含中点，超额需求失去凸值，标准存在性停机。这是<a href="/econ/convex-preference">凸偏好</a>必须在均衡之前就钉死的原因。Kakutani 不发明凸，它消费凸。</p><p><span class="marginnote">Kakutani 仍是存在性。多重纳什、多重均衡是常态。选择均衡要精炼或稳定性，不在本课。</span></p><p><span class="marginnote">直觉类比：把 \\(\\Phi(0)=\\{1\\}\\)、\\(\\Phi(1)=\\{0\\}\\) 想成两家互相把客人推给对方的旅店——每个点都被推走，谁也停不下来，所以没有不动点。病根不在「紧」，而在值不凸：值只有两个端点、没有任何「中间地带」可以落脚。凸值就是给点一个可以停留的中间集合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用 Kakutani 前核对定义域紧凸、像落在定义域里、值凸紧非空、上半连续。连续目标在紧凸可行集上的最优对应，在偏好连续凸、预算连续且紧时，满足这些——Berge 极大值定理给非空紧与 UHC，凸偏好给凸值。后课<a href="/econ/uhc-correspondence">上半连续对应</a>把 UHC 与 Berge 写清楚；本课只要求：没有 UHC，Kakutani 的假设不齐。</p><p>近似办法：用连续函数 \\(f_\\varepsilon\\) 在 \\(\\varepsilon\\)-邻域里挑 \\(\\Phi\\) 的点（Michael 选择在凸值时可用），对 \\(f_\\varepsilon\\) 用 Brouwer，令 \\(\\varepsilon\\to 0\\) 用闭图收极限。这解释了为何 Kakutani 看起来像「集值 Brouwer」。</p><p><span class="marginnote">「上半连续」可以先翻译成「图是闭的」：若 \\(x_n\\to x\\)、\\(y_n\\in\\Phi(x_n)\\) 且 \\(y_n\\to y\\)，则 \\(y\\) 仍在 \\(\\Phi(x)\\) 里。直觉上，对应的像在极限处不会突然缩小或甩出新点——这是保证「近似不动点能收成真不动点」的那条保险，少了它整套证明在极限处漏气。</span></p>',14)),(r(),E(l,null,{default:i(()=>[B(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20BR%5B%22Brouwer%EF%BC%9A%E8%BF%9E%E7%BB%AD%E5%87%BD%E6%95%B0%22%5D%20--%3E%20K%5B%22Kakutani%EF%BC%9AUHC%20%E5%87%B8%E5%80%BC%E5%AF%B9%E5%BA%94%22%5D%0A%20%20K%20--%3E%20GE%5B%22%E8%B6%85%E9%A2%9D%E9%9C%80%E6%B1%82%E9%9B%86%E5%80%BC%E6%97%B6%E7%9A%84%E5%87%BA%E6%B8%85%22%5D%0A%20%20K%20--%3E%20MS%5B%22%E6%B7%B7%E5%90%88%E7%AD%96%E7%95%A5%E7%BA%B3%E4%BB%80%22%5D%0A%20%20CONV%5B%22%E5%87%B8%E5%80%BC%22%5D%20--%3E%20K%0A%20%20UHC%5B%22%E4%B8%8A%E5%8D%8A%E8%BF%9E%E7%BB%AD%22%5D%20--%3E%20K%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[e("\\(x\\) 不在 \\(\\Phi(x)\\) 里时，凸值让你能用"),n("a",{href:"/econ/separating-hyperplane"},"分离超平面"),e("把 \\(x\\) 与 \\(\\Phi(x)\\) 分开，造出一个连续的「朝像走」的方向。UHC 保证这个方向不会在极限处突然跳开。于是可以造辅助的连续自映射，Brouwer 给出近似不动点，闭图把近似收成真正的 \\(x\\in\\Phi(x)\\)。分离再一次成为存在性的引擎：没有凸，分离失败，辅助映射造不出来。")],-1)),(r(),E(l,null,{default:i(()=>[B(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20XNIN%5B%22x%20%E4%B8%8D%E5%9C%A8%20Phi(x)%20%E9%87%8C%22%5D%20--%3E%20SEP%5B%22%E5%87%B8%E5%80%BC%3A%20%E5%88%86%E7%A6%BB%E8%B6%85%E5%B9%B3%E9%9D%A2%E9%9A%94%E5%BC%80%20x%20%E4%B8%8E%E5%83%8F%22%5D%0A%20%20SEP%20--%3E%20DIR%5B%22%E9%80%A0%E8%BF%9E%E7%BB%AD%E7%9A%84%E6%9C%9D%E5%83%8F%E8%B5%B0%E6%96%B9%E5%90%91%22%5D%0A%20%20UHCH%5B%22UHC%22%5D%20--%3E%20NOJUMP%5B%22%E6%96%B9%E5%90%91%E5%9C%A8%E6%9E%81%E9%99%90%E5%A4%84%E4%B8%8D%E8%B7%B3%E5%BC%80%22%5D%0A%20%20DIR%20--%3E%20AUX%5B%22%E8%BE%85%E5%8A%A9%E8%BF%9E%E7%BB%AD%E8%87%AA%E6%98%A0%E5%B0%84%22%5D%0A%20%20NOJUMP%20--%3E%20AUX%0A%20%20AUX%20--%3E%20BR%5B%22%E5%AF%B9%E8%BE%85%E5%8A%A9%E6%98%A0%E5%B0%84%E7%94%A8%20Brouwer%22%5D%0A%20%20BR%20--%3E%20LIM%5B%22%E9%97%AD%E5%9B%BE%E6%94%B6%E6%9E%81%E9%99%90%3A%20x%20%E5%B1%9E%E4%BA%8E%20Phi(x)%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>与压缩的对比依旧：Kakutani 不给唯一、不给 Picard。值函数迭代走压缩；均衡存在走 Kakutani。两者都叫不动点，假设与产物不同，不要混用迭代去「算」一般均衡的 Kakutani 点还指望全局唯一。</p><p><span class="marginnote">常见误区：把 Kakutani 当成「能算出均衡的算法」。它只承诺至少存在一个不动点，不给唯一性、也不给找法；带迭代收敛的是压缩映射那一族。把两者混为一谈，就会拿错误的工具去追不存在的唯一解。</span></p><p><span class="marginnote">无限维要 Glicksberg 一类推广。连续时间或函数价格空间上的均衡有时走那条；有限商品主干停在 Kakutani。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给 UHC 的 \\(\\varepsilon\\)-\\(\\delta\\) 定义，不证 Berge，不写 Nash 的全部公理。不要把 Kakutani 用到非凸生产（固定成本）上还声称标准存在性成立——那需要企业数原子、混合或递增成本的修补。下一课把「上半连续」从黑箱变成可检查的定义，并接到需求对应与极大值定理。</p><p>后课默认：集值需求、集值最佳反应，存在性靠 Kakutani；缺凸值就回到非凸对照，不硬套本定理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kakutani：紧凸上 UHC、非空紧凸值自对应有不动点。</li><li>Brouwer 是单值特例；混合纳什与集值超额需求是正例。</li><li>凸值来自凸偏好/线性化混合；没有凸，分离辅助失败。</li><li>存在不是唯一，也不是计算程序。</li><li>下一课：<a href="/econ/uhc-correspondence">上半连续对应</a>。</li><li>出处：Kakutani, <em>Duke Math. J.</em> 1941；Debreu, <em>Theory of Value</em>；MWG 第 17 章。</li></ul>',8))])}const D=s(u,[["render",d]]);export{f as __pageData,D as default};
